begin;
create type public.warehouse_status as enum('active','inactive','temporarily_closed');
create type public.inventory_record_status as enum('active','inactive');
create type public.lot_status as enum('pending_receipt','received','pending_qc','available','quarantined','rejected','depleted','expired','recalled');
create type public.receiving_status as enum('draft','in_progress','completed','cancelled');
create type public.receiving_line_status as enum('pending','received','discrepancy','rejected');
create type public.inventory_transaction_type as enum('receipt','adjustment_in','adjustment_out','transfer_in','transfer_out','reserve','release_reservation','quarantine','release_quarantine','damage','expiration','fulfillment','return');
create type public.reservation_status as enum('active','released','fulfilled','cancelled');

insert into public.permissions(code,name,description) values
('warehouses.view','View warehouses','View internal warehouses and locations.'),('warehouses.manage','Manage warehouses','Create and update internal warehouses and locations.'),
('inventory.view','View inventory','View internal inventory balances and ledger.'),('inventory.receive','Receive inventory','Create and complete receiving events.'),
('inventory.adjust','Adjust inventory','Post controlled delta-based inventory adjustments.'),('inventory.transfer','Transfer inventory','Transfer stock between authorized locations.'),
('inventory.quarantine','Quarantine inventory','Quarantine and release eligible stock.'),('inventory.view_lots','View inventory lots','View lot and expiration details.'),
('inventory.manage_lots','Manage inventory lots','Create and update lot metadata and status.') on conflict(code) do nothing;
insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where r.code='SUPER_ADMIN' or(r.code='ADMIN' and p.code in('warehouses.view','warehouses.manage','inventory.view','inventory.receive','inventory.adjust','inventory.transfer','inventory.quarantine','inventory.view_lots','inventory.manage_lots')) or(r.code='WAREHOUSE' and p.code in('warehouses.view','inventory.view','inventory.receive','inventory.transfer','inventory.quarantine','inventory.view_lots')) on conflict do nothing;

create table public.warehouses(id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,warehouse_code text not null check(char_length(trim(warehouse_code)) between 1 and 40),warehouse_name text not null check(char_length(trim(warehouse_name)) between 1 and 160),status public.warehouse_status not null default'active',address_line_1 text,address_line_2 text,city text,region text,postal_code text,country text not null default'US',timezone text not null default'UTC',contact_name text,contact_email text,contact_phone text,internal_notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,warehouse_code),unique(organization_id,id));
create table public.warehouse_locations(id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,warehouse_id uuid not null,location_code text not null check(char_length(trim(location_code)) between 1 and 60),location_name text not null check(char_length(trim(location_name)) between 1 and 160),location_type text not null check(char_length(trim(location_type)) between 1 and 80),status public.inventory_record_status not null default'active',description text,internal_notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(organization_id,warehouse_id) references public.warehouses(organization_id,id) on delete restrict,unique(warehouse_id,location_code),unique(organization_id,id),unique(organization_id,warehouse_id,id));
create table public.inventory_lots(id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,product_variant_id uuid not null,lot_number text not null check(char_length(trim(lot_number)) between 1 and 120),manufacturer_lot text,manufactured_date date,received_date date,expiration_date date,bud_date date,quantity_received numeric(20,6) not null default 0 check(quantity_received>=0),unit_of_measure text not null check(char_length(trim(unit_of_measure)) between 1 and 40),acquisition_reference text,status public.lot_status not null default'pending_receipt',internal_notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(organization_id,product_variant_id) references public.product_variants(organization_id,id) on delete restrict,check(expiration_date is null or manufactured_date is null or expiration_date>=manufactured_date),check(bud_date is null or manufactured_date is null or bud_date>=manufactured_date),unique(organization_id,product_variant_id,lot_number),unique(organization_id,id),unique(organization_id,product_variant_id,id));
create table public.inventory_lot_sources(lot_id uuid primary key references public.inventory_lots(id) on delete cascade,organization_id uuid not null references public.organizations(id) on delete restrict,supplier_id uuid,supplier_product_variant_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(organization_id,lot_id) references public.inventory_lots(organization_id,id) on delete cascade,foreign key(organization_id,supplier_id) references public.suppliers(organization_id,id) on delete restrict,foreign key(organization_id,supplier_product_variant_id) references public.supplier_product_variants(organization_id,id) on delete restrict);
create table public.receivings(id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,warehouse_id uuid not null,receiving_reference text not null,received_at timestamptz not null,received_by_user_id uuid not null references auth.users(id) on delete restrict,status public.receiving_status not null default'draft',notes text,idempotency_key text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(organization_id,warehouse_id) references public.warehouses(organization_id,id) on delete restrict,unique(organization_id,receiving_reference),unique(organization_id,idempotency_key),unique(organization_id,id));
create table public.receiving_lines(id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,receiving_id uuid not null,product_variant_id uuid not null,lot_id uuid not null,destination_location_id uuid not null,quantity_expected numeric(20,6),quantity_received numeric(20,6) not null check(quantity_received>0),discrepancy_quantity numeric(20,6) not null default 0,discrepancy_reason text,status public.receiving_line_status not null default'received',expiration_date date,bud_date date,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(organization_id,receiving_id) references public.receivings(organization_id,id) on delete restrict,foreign key(organization_id,product_variant_id,lot_id) references public.inventory_lots(organization_id,product_variant_id,id) on delete restrict,foreign key(organization_id,destination_location_id) references public.warehouse_locations(organization_id,id) on delete restrict);
create table public.inventory_balances(id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,warehouse_id uuid not null,location_id uuid not null,product_variant_id uuid not null,lot_id uuid not null,physical_quantity numeric(20,6) not null default 0 check(physical_quantity>=0),available_quantity numeric(20,6) not null default 0 check(available_quantity>=0),reserved_quantity numeric(20,6) not null default 0 check(reserved_quantity>=0),quarantined_quantity numeric(20,6) not null default 0 check(quarantined_quantity>=0),damaged_quantity numeric(20,6) not null default 0 check(damaged_quantity>=0),updated_at timestamptz not null default now(),foreign key(organization_id,warehouse_id,location_id) references public.warehouse_locations(organization_id,warehouse_id,id) on delete restrict,foreign key(organization_id,product_variant_id,lot_id) references public.inventory_lots(organization_id,product_variant_id,id) on delete restrict,check(available_quantity+reserved_quantity+quarantined_quantity+damaged_quantity<=physical_quantity),unique(organization_id,warehouse_id,location_id,lot_id));
create table public.inventory_transactions(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete restrict,warehouse_id uuid not null,location_id uuid not null,lot_id uuid not null,product_variant_id uuid not null,transaction_type public.inventory_transaction_type not null,physical_delta numeric(20,6) not null default 0,available_delta numeric(20,6) not null default 0,reserved_delta numeric(20,6) not null default 0,quarantined_delta numeric(20,6) not null default 0,damaged_delta numeric(20,6) not null default 0,reference_type text not null,reference_id text not null,actor_user_id uuid not null references auth.users(id) on delete restrict,reason text,idempotency_key text not null,sequence_number smallint not null default 1,metadata jsonb not null default'{}',created_at timestamptz not null default now(),foreign key(organization_id,warehouse_id,location_id) references public.warehouse_locations(organization_id,warehouse_id,id) on delete restrict,foreign key(organization_id,product_variant_id,lot_id) references public.inventory_lots(organization_id,product_variant_id,id) on delete restrict,unique(organization_id,idempotency_key,sequence_number));
create table public.inventory_reservations(id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,warehouse_id uuid not null,location_id uuid not null,product_variant_id uuid not null,lot_id uuid not null,quantity numeric(20,6) not null check(quantity>0),status public.reservation_status not null default'active',source_type text not null,source_id text not null,created_by_user_id uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),released_at timestamptz,fulfilled_at timestamptz,foreign key(organization_id,warehouse_id,location_id) references public.warehouse_locations(organization_id,warehouse_id,id) on delete restrict,foreign key(organization_id,product_variant_id,lot_id) references public.inventory_lots(organization_id,product_variant_id,id) on delete restrict,unique(organization_id,source_type,source_id,lot_id));

create index inventory_lots_fefo_idx on public.inventory_lots(organization_id,product_variant_id,expiration_date,bud_date) where status='available';create index inventory_transactions_history_idx on public.inventory_transactions(organization_id,created_at desc);create index inventory_balances_lookup_idx on public.inventory_balances(organization_id,product_variant_id,warehouse_id);
do $$declare t text;begin foreach t in array array['warehouses','warehouse_locations','inventory_lots','inventory_lot_sources','receivings','receiving_lines'] loop execute format('create trigger %I_set_updated_at before update on public.%I for each row execute function private.set_updated_at()',t,t);end loop;end $$;

create view public.inventory_availability with(security_invoker=true) as select b.*,case when l.status='available' and coalesce(l.expiration_date,current_date)>=current_date and coalesce(l.bud_date,current_date)>=current_date then b.available_quantity else 0 end as eligible_available_quantity,case when l.expiration_date<current_date or l.bud_date<current_date then b.physical_quantity else 0 end as expired_quantity from public.inventory_balances b join public.inventory_lots l on l.id=b.lot_id;

do $$declare t text;begin foreach t in array array['warehouses','warehouse_locations','inventory_lots','inventory_lot_sources','receivings','receiving_lines','inventory_balances','inventory_transactions','inventory_reservations'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon',t);end loop;end $$;
create policy warehouse_read on public.warehouses for select to authenticated using(private.has_permission(organization_id,'warehouses.view'));create policy location_read on public.warehouse_locations for select to authenticated using(private.has_permission(organization_id,'warehouses.view'));create policy lots_read on public.inventory_lots for select to authenticated using(private.has_permission(organization_id,'inventory.view_lots'));create policy lot_sources_read on public.inventory_lot_sources for select to authenticated using(private.has_permission(organization_id,'suppliers.view'));create policy receivings_read on public.receivings for select to authenticated using(private.has_permission(organization_id,'inventory.view'));create policy receiving_lines_read on public.receiving_lines for select to authenticated using(private.has_permission(organization_id,'inventory.view'));create policy balances_read on public.inventory_balances for select to authenticated using(private.has_permission(organization_id,'inventory.view'));create policy transactions_read on public.inventory_transactions for select to authenticated using(private.has_permission(organization_id,'inventory.view'));create policy reservations_read on public.inventory_reservations for select to authenticated using(private.has_permission(organization_id,'inventory.view'));
grant select on public.warehouses,public.warehouse_locations,public.inventory_lots,public.inventory_lot_sources,public.receivings,public.receiving_lines,public.inventory_balances,public.inventory_transactions,public.inventory_reservations,public.inventory_availability to authenticated;grant select,insert,update,delete on public.warehouses,public.warehouse_locations,public.inventory_lots,public.inventory_lot_sources,public.receivings,public.receiving_lines,public.inventory_balances,public.inventory_transactions,public.inventory_reservations to service_role;grant usage,select on sequence public.inventory_transactions_id_seq to service_role;

create function private.require_inventory_org(org_id uuid,permission_code text,actor_id uuid) returns void language plpgsql security definer set search_path='' as $$begin if actor_id is null or not private.has_permission(org_id,permission_code,actor_id) then raise exception'Not authorized'using errcode='42501';end if;if not exists(select 1 from public.organizations where id=org_id and status='active'and organization_type in('fulfillment_company','white_label'))then raise exception'Active fulfillment organization required'using errcode='42501';end if;end $$;
create function private.apply_inventory_delta(org_id uuid,warehouse uuid,location uuid,variant uuid,lot uuid,tx text,pd numeric,ad numeric,rd numeric,qd numeric,dd numeric,ref_type text,ref_id text,actor uuid,why text,request_key text,seq integer) returns bigint language plpgsql security definer set search_path='' as $$declare balance public.inventory_balances%rowtype;txid bigint;begin if exists(select 1 from public.inventory_transactions where organization_id=org_id and idempotency_key=request_key and sequence_number=seq)then select id into txid from public.inventory_transactions where organization_id=org_id and idempotency_key=request_key and sequence_number=seq;return txid;end if;if not exists(select 1 from public.warehouse_locations wl join public.warehouses w on w.id=wl.warehouse_id where wl.id=location and wl.warehouse_id=warehouse and wl.organization_id=org_id and wl.status='active'and w.status='active')or not exists(select 1 from public.inventory_lots l where l.id=lot and l.product_variant_id=variant and l.organization_id=org_id)then raise exception'Invalid inventory relationship'using errcode='22023';end if;insert into public.inventory_balances(organization_id,warehouse_id,location_id,product_variant_id,lot_id)values(org_id,warehouse,location,variant,lot)on conflict(organization_id,warehouse_id,location_id,lot_id)do nothing;select*into balance from public.inventory_balances where organization_id=org_id and warehouse_id=warehouse and location_id=location and lot_id=lot for update;if balance.physical_quantity+pd<0 or balance.available_quantity+ad<0 or balance.reserved_quantity+rd<0 or balance.quarantined_quantity+qd<0 or balance.damaged_quantity+dd<0 or balance.available_quantity+ad+balance.reserved_quantity+rd+balance.quarantined_quantity+qd+balance.damaged_quantity+dd>balance.physical_quantity+pd then raise exception'Insufficient or invalid inventory balance'using errcode='23514';end if;update public.inventory_balances set physical_quantity=physical_quantity+pd,available_quantity=available_quantity+ad,reserved_quantity=reserved_quantity+rd,quarantined_quantity=quarantined_quantity+qd,damaged_quantity=damaged_quantity+dd,updated_at=now()where id=balance.id;insert into public.inventory_transactions(organization_id,warehouse_id,location_id,lot_id,product_variant_id,transaction_type,physical_delta,available_delta,reserved_delta,quarantined_delta,damaged_delta,reference_type,reference_id,actor_user_id,reason,idempotency_key,sequence_number)values(org_id,warehouse,location,lot,variant,tx::public.inventory_transaction_type,pd,ad,rd,qd,dd,ref_type,ref_id,actor,why,request_key,seq)returning id into txid;return txid;end $$;
revoke all on function private.require_inventory_org(uuid,text,uuid),private.apply_inventory_delta(uuid,uuid,uuid,uuid,uuid,text,numeric,numeric,numeric,numeric,numeric,text,text,uuid,text,text,integer) from public,anon,authenticated;

create function public.admin_save_warehouse(target_id uuid,target_organization_id uuid,target_code text,target_name text,target_status public.warehouse_status,target_city text,target_region text,target_postal text,target_country text,target_timezone text,target_notes text)returns uuid language plpgsql security definer set search_path='' as $$declare rid uuid;begin perform private.require_inventory_org(target_organization_id,'warehouses.manage',auth.uid());if target_id is null then insert into public.warehouses(organization_id,warehouse_code,warehouse_name,status,city,region,postal_code,country,timezone,internal_notes)values(target_organization_id,upper(trim(target_code)),trim(target_name),target_status,nullif(trim(target_city),''),nullif(trim(target_region),''),nullif(trim(target_postal),''),trim(target_country),trim(target_timezone),nullif(trim(target_notes),''))returning id into rid;else update public.warehouses set warehouse_code=upper(trim(target_code)),warehouse_name=trim(target_name),status=target_status,city=nullif(trim(target_city),''),region=nullif(trim(target_region),''),postal_code=nullif(trim(target_postal),''),country=trim(target_country),timezone=trim(target_timezone),internal_notes=nullif(trim(target_notes),'')where id=target_id and organization_id=target_organization_id returning id into rid;if rid is null then raise exception'Warehouse not found'using errcode='P0002';end if;end if;perform private.write_audit_event(auth.uid(),target_organization_id,case when target_id is null then'warehouse.created'else'warehouse.updated'end,'warehouse',rid::text,jsonb_build_object('code',target_code,'status',target_status));return rid;end $$;
create function public.admin_save_warehouse_location(target_id uuid,target_organization_id uuid,target_warehouse_id uuid,target_code text,target_name text,target_type text,target_status public.inventory_record_status,target_description text,target_notes text)returns uuid language plpgsql security definer set search_path='' as $$declare rid uuid;begin perform private.require_inventory_org(target_organization_id,'warehouses.manage',auth.uid());if not exists(select 1 from public.warehouses where id=target_warehouse_id and organization_id=target_organization_id)then raise exception'Invalid warehouse'using errcode='22023';end if;if target_id is null then insert into public.warehouse_locations(organization_id,warehouse_id,location_code,location_name,location_type,status,description,internal_notes)values(target_organization_id,target_warehouse_id,upper(trim(target_code)),trim(target_name),trim(target_type),target_status,nullif(trim(target_description),''),nullif(trim(target_notes),''))returning id into rid;else update public.warehouse_locations set warehouse_id=target_warehouse_id,location_code=upper(trim(target_code)),location_name=trim(target_name),location_type=trim(target_type),status=target_status,description=nullif(trim(target_description),''),internal_notes=nullif(trim(target_notes),'')where id=target_id and organization_id=target_organization_id returning id into rid;if rid is null then raise exception'Location not found'using errcode='P0002';end if;end if;perform private.write_audit_event(auth.uid(),target_organization_id,case when target_id is null then'warehouse_location.created'else'warehouse_location.updated'end,'warehouse_location',rid::text,jsonb_build_object('code',target_code,'type',target_type));return rid;end $$;
create function public.admin_save_inventory_lot(target_id uuid,target_organization_id uuid,target_variant_id uuid,target_lot_number text,target_manufacturer_lot text,target_manufactured date,target_received date,target_expiration date,target_bud date,target_uom text,target_status public.lot_status,target_notes text,target_supplier_id uuid,target_supplier_relationship_id uuid)returns uuid language plpgsql security definer set search_path='' as $$declare rid uuid;begin perform private.require_inventory_org(target_organization_id,'inventory.manage_lots',auth.uid());if not exists(select 1 from public.product_variants where id=target_variant_id and organization_id=target_organization_id)then raise exception'Invalid variant'using errcode='22023';end if;if(target_supplier_id is not null or target_supplier_relationship_id is not null)and not private.has_permission(target_organization_id,'suppliers.view',auth.uid())then raise exception'Supplier access required'using errcode='42501';end if;if target_id is null then insert into public.inventory_lots(organization_id,product_variant_id,lot_number,manufacturer_lot,manufactured_date,received_date,expiration_date,bud_date,unit_of_measure,status,internal_notes)values(target_organization_id,target_variant_id,trim(target_lot_number),nullif(trim(target_manufacturer_lot),''),target_manufactured,target_received,target_expiration,target_bud,trim(target_uom),target_status,nullif(trim(target_notes),''))returning id into rid;else update public.inventory_lots set manufacturer_lot=nullif(trim(target_manufacturer_lot),''),manufactured_date=target_manufactured,received_date=target_received,expiration_date=target_expiration,bud_date=target_bud,unit_of_measure=trim(target_uom),status=target_status,internal_notes=nullif(trim(target_notes),'')where id=target_id and organization_id=target_organization_id and product_variant_id=target_variant_id returning id into rid;if rid is null then raise exception'Lot not found'using errcode='P0002';end if;end if;if target_supplier_id is not null or target_supplier_relationship_id is not null then insert into public.inventory_lot_sources(lot_id,organization_id,supplier_id,supplier_product_variant_id)values(rid,target_organization_id,target_supplier_id,target_supplier_relationship_id)on conflict(lot_id)do update set supplier_id=excluded.supplier_id,supplier_product_variant_id=excluded.supplier_product_variant_id;end if;perform private.write_audit_event(auth.uid(),target_organization_id,case when target_id is null then'lot.created'else'lot.updated'end,'inventory_lot',rid::text,jsonb_build_object('status',target_status,'lot_number',target_lot_number));return rid;end $$;

create function public.admin_receive_inventory(target_organization_id uuid,target_warehouse_id uuid,target_location_id uuid,target_lot_id uuid,target_quantity numeric,target_reference text,target_expected numeric,target_discrepancy_reason text,target_idempotency_key text)returns uuid language plpgsql security definer set search_path='' as $$declare actor uuid:=auth.uid();lotrow public.inventory_lots%rowtype;receiving_id uuid;is_expired boolean;begin perform private.require_inventory_org(target_organization_id,'inventory.receive',actor);if target_quantity<=0 or char_length(target_idempotency_key)<8 then raise exception'Invalid receipt'using errcode='22023';end if;select*into lotrow from public.inventory_lots where id=target_lot_id and organization_id=target_organization_id for update;if lotrow.id is null or lotrow.status in('rejected','expired','recalled')then raise exception'Ineligible lot'using errcode='22023';end if;is_expired:=lotrow.expiration_date<current_date or lotrow.bud_date<current_date;select id into receiving_id from public.receivings where organization_id=target_organization_id and idempotency_key=target_idempotency_key;if receiving_id is not null then return receiving_id;end if;insert into public.receivings(organization_id,warehouse_id,receiving_reference,received_at,received_by_user_id,status,notes,idempotency_key)values(target_organization_id,target_warehouse_id,trim(target_reference),now(),actor,'completed',null,target_idempotency_key)returning id into receiving_id;insert into public.receiving_lines(organization_id,receiving_id,product_variant_id,lot_id,destination_location_id,quantity_expected,quantity_received,discrepancy_quantity,discrepancy_reason,status,expiration_date,bud_date)values(target_organization_id,receiving_id,lotrow.product_variant_id,lotrow.id,target_location_id,target_expected,target_quantity,case when target_expected is null then 0 else target_quantity-target_expected end,nullif(trim(target_discrepancy_reason),''),case when target_expected is not null and target_expected<>target_quantity then'discrepancy'::public.receiving_line_status else'received'::public.receiving_line_status end,lotrow.expiration_date,lotrow.bud_date);update public.inventory_lots set quantity_received=quantity_received+target_quantity,received_date=coalesce(received_date,current_date),status=case when is_expired then'expired'::public.lot_status when status in('pending_receipt','received')then'available'else status end where id=lotrow.id;perform private.apply_inventory_delta(target_organization_id,target_warehouse_id,target_location_id,lotrow.product_variant_id,lotrow.id,'receipt',target_quantity,case when is_expired then 0 else target_quantity end,0,0,0,'receiving',receiving_id::text,actor,'Inventory receipt',target_idempotency_key,1);perform private.write_audit_event(actor,target_organization_id,'receiving.completed','receiving',receiving_id::text,jsonb_build_object('warehouse_id',target_warehouse_id,'lot_id',target_lot_id,'quantity',target_quantity,'expired',is_expired));return receiving_id;end $$;

create function public.admin_adjust_inventory(target_organization_id uuid,target_warehouse_id uuid,target_location_id uuid,target_lot_id uuid,target_quantity_delta numeric,target_reason text,target_idempotency_key text)returns bigint language plpgsql security definer set search_path='' as $$declare lotrow public.inventory_lots%rowtype;txid bigint;begin perform private.require_inventory_org(target_organization_id,'inventory.adjust',auth.uid());if target_quantity_delta=0 or char_length(trim(target_reason))<3 then raise exception'Invalid adjustment'using errcode='22023';end if;select*into lotrow from public.inventory_lots where id=target_lot_id and organization_id=target_organization_id;if lotrow.id is null then raise exception'Invalid lot'using errcode='22023';end if;if target_quantity_delta>0 and(lotrow.status<>'available'or coalesce(lotrow.expiration_date,current_date)<current_date or coalesce(lotrow.bud_date,current_date)<current_date)then raise exception'Lot is not eligible for available inventory'using errcode='22023';end if;txid:=private.apply_inventory_delta(target_organization_id,target_warehouse_id,target_location_id,lotrow.product_variant_id,lotrow.id,case when target_quantity_delta>0 then'adjustment_in'else'adjustment_out'end,target_quantity_delta,target_quantity_delta,0,0,0,'adjustment',target_idempotency_key,auth.uid(),target_reason,target_idempotency_key,1);perform private.write_audit_event(auth.uid(),target_organization_id,'inventory.adjusted','inventory_lot',target_lot_id::text,jsonb_build_object('delta',target_quantity_delta,'reason',target_reason,'transaction_id',txid));return txid;end $$;
create function public.admin_transfer_inventory(target_organization_id uuid,target_source_warehouse_id uuid,target_source_location_id uuid,target_destination_warehouse_id uuid,target_destination_location_id uuid,target_lot_id uuid,target_quantity numeric,target_reason text,target_idempotency_key text)returns bigint[] language plpgsql security definer set search_path='' as $$declare lotrow public.inventory_lots%rowtype;outid bigint;inid bigint;begin perform private.require_inventory_org(target_organization_id,'inventory.transfer',auth.uid());if target_quantity<=0 or target_source_location_id=target_destination_location_id then raise exception'Invalid transfer'using errcode='22023';end if;select*into lotrow from public.inventory_lots where id=target_lot_id and organization_id=target_organization_id;if lotrow.id is null or lotrow.status<>'available'or coalesce(lotrow.expiration_date,current_date)<current_date or coalesce(lotrow.bud_date,current_date)<current_date then raise exception'Ineligible lot'using errcode='22023';end if;outid:=private.apply_inventory_delta(target_organization_id,target_source_warehouse_id,target_source_location_id,lotrow.product_variant_id,lotrow.id,'transfer_out',-target_quantity,-target_quantity,0,0,0,'transfer',target_idempotency_key,auth.uid(),target_reason,target_idempotency_key,1);inid:=private.apply_inventory_delta(target_organization_id,target_destination_warehouse_id,target_destination_location_id,lotrow.product_variant_id,lotrow.id,'transfer_in',target_quantity,target_quantity,0,0,0,'transfer',target_idempotency_key,auth.uid(),target_reason,target_idempotency_key,2);perform private.write_audit_event(auth.uid(),target_organization_id,'inventory.transferred','inventory_lot',target_lot_id::text,jsonb_build_object('quantity',target_quantity,'source_location_id',target_source_location_id,'destination_location_id',target_destination_location_id));return array[outid,inid];end $$;
create function public.admin_set_inventory_quarantine(target_organization_id uuid,target_warehouse_id uuid,target_location_id uuid,target_lot_id uuid,target_quantity numeric,should_quarantine boolean,target_reason text,target_idempotency_key text)returns bigint language plpgsql security definer set search_path='' as $$declare lotrow public.inventory_lots%rowtype;txid bigint;begin perform private.require_inventory_org(target_organization_id,'inventory.quarantine',auth.uid());if target_quantity<=0 then raise exception'Invalid quantity'using errcode='22023';end if;select*into lotrow from public.inventory_lots where id=target_lot_id and organization_id=target_organization_id for update;if lotrow.id is null then raise exception'Invalid lot'using errcode='22023';end if;if not should_quarantine and(lotrow.status in('rejected','expired','recalled')or coalesce(lotrow.expiration_date,current_date)<current_date or coalesce(lotrow.bud_date,current_date)<current_date)then raise exception'Lot cannot be released'using errcode='22023';end if;txid:=private.apply_inventory_delta(target_organization_id,target_warehouse_id,target_location_id,lotrow.product_variant_id,lotrow.id,case when should_quarantine then'quarantine'else'release_quarantine'end,0,case when should_quarantine then-target_quantity else target_quantity end,0,case when should_quarantine then target_quantity else-target_quantity end,0,'quarantine',target_idempotency_key,auth.uid(),target_reason,target_idempotency_key,1);perform private.write_audit_event(auth.uid(),target_organization_id,case when should_quarantine then'inventory.quarantined'else'inventory.quarantine_released'end,'inventory_lot',target_lot_id::text,jsonb_build_object('quantity',target_quantity,'reason',target_reason));return txid;end $$;

create function public.admin_reserve_inventory(target_organization_id uuid,target_warehouse_id uuid,target_location_id uuid,target_lot_id uuid,target_quantity numeric,target_source_type text,target_source_id text,target_idempotency_key text)returns uuid language plpgsql security definer set search_path='' as $$declare lotrow public.inventory_lots%rowtype;reservation_id uuid;begin perform private.require_inventory_org(target_organization_id,'inventory.adjust',auth.uid());if target_quantity<=0 then raise exception'Invalid reservation'using errcode='22023';end if;select*into lotrow from public.inventory_lots where id=target_lot_id and organization_id=target_organization_id;if lotrow.id is null or lotrow.status<>'available'or coalesce(lotrow.expiration_date,current_date)<current_date or coalesce(lotrow.bud_date,current_date)<current_date then raise exception'Ineligible lot'using errcode='22023';end if;select id into reservation_id from public.inventory_reservations where organization_id=target_organization_id and source_type=target_source_type and source_id=target_source_id and lot_id=target_lot_id;if reservation_id is not null then return reservation_id;end if;insert into public.inventory_reservations(organization_id,warehouse_id,location_id,product_variant_id,lot_id,quantity,source_type,source_id,created_by_user_id)values(target_organization_id,target_warehouse_id,target_location_id,lotrow.product_variant_id,lotrow.id,target_quantity,trim(target_source_type),trim(target_source_id),auth.uid())returning id into reservation_id;perform private.apply_inventory_delta(target_organization_id,target_warehouse_id,target_location_id,lotrow.product_variant_id,lotrow.id,'reserve',0,-target_quantity,target_quantity,0,0,'reservation',reservation_id::text,auth.uid(),'Inventory reserved',target_idempotency_key,1);perform private.write_audit_event(auth.uid(),target_organization_id,'inventory.reserved','inventory_reservation',reservation_id::text,jsonb_build_object('quantity',target_quantity,'source_type',target_source_type));return reservation_id;end $$;
create function public.admin_release_inventory_reservation(target_organization_id uuid,target_reservation_id uuid,target_idempotency_key text)returns bigint language plpgsql security definer set search_path='' as $$declare r public.inventory_reservations%rowtype;lotrow public.inventory_lots%rowtype;txid bigint;begin perform private.require_inventory_org(target_organization_id,'inventory.adjust',auth.uid());select*into r from public.inventory_reservations where id=target_reservation_id and organization_id=target_organization_id for update;if r.id is null or r.status<>'active'then raise exception'Active reservation not found'using errcode='22023';end if;select*into lotrow from public.inventory_lots where id=r.lot_id;if lotrow.status in('rejected','expired','recalled')or coalesce(lotrow.expiration_date,current_date)<current_date or coalesce(lotrow.bud_date,current_date)<current_date then raise exception'Inventory is no longer releasable'using errcode='22023';end if;txid:=private.apply_inventory_delta(target_organization_id,r.warehouse_id,r.location_id,r.product_variant_id,r.lot_id,'release_reservation',0,r.quantity,-r.quantity,0,0,'reservation',r.id::text,auth.uid(),'Reservation released',target_idempotency_key,1);update public.inventory_reservations set status='released',released_at=now()where id=r.id;perform private.write_audit_event(auth.uid(),target_organization_id,'inventory.reservation_released','inventory_reservation',r.id::text,jsonb_build_object('quantity',r.quantity));return txid;end $$;
create function public.admin_mark_inventory_damaged(target_organization_id uuid,target_warehouse_id uuid,target_location_id uuid,target_lot_id uuid,target_quantity numeric,target_reason text,target_idempotency_key text)returns bigint language plpgsql security definer set search_path='' as $$declare lotrow public.inventory_lots%rowtype;txid bigint;begin perform private.require_inventory_org(target_organization_id,'inventory.adjust',auth.uid());if target_quantity<=0 then raise exception'Invalid damage operation'using errcode='22023';end if;select*into lotrow from public.inventory_lots where id=target_lot_id and organization_id=target_organization_id;if lotrow.id is null then raise exception'Invalid lot'using errcode='22023';end if;txid:=private.apply_inventory_delta(target_organization_id,target_warehouse_id,target_location_id,lotrow.product_variant_id,lotrow.id,'damage',0,-target_quantity,0,0,target_quantity,'damage',target_idempotency_key,auth.uid(),target_reason,target_idempotency_key,1);perform private.write_audit_event(auth.uid(),target_organization_id,'inventory.damaged','inventory_lot',target_lot_id::text,jsonb_build_object('quantity',target_quantity,'reason',target_reason));return txid;end $$;

